return $input.all().map(i => {
  const j = i.json;
  let items = j.items;
  if (typeof items === 'string') { try { items = JSON.parse(items); } catch (e) { items = []; } }
  if (!Array.isArray(items) || !items.length || !j.rep_email) return null;
  const lines = items.map(x => `• ${x.account} — ${x.action_type} (waiting ${x.age_days} day${x.age_days === 1 ? '' : 's'})`).join('\n');
  const n = items.length;
  return { json: {
    rep_email: j.rep_email,
    subject: `${n} touch${n === 1 ? ' is' : 'es are'} waiting on you`,
    body: `These recommended touches have been sitting for 2+ days:\n\n${lines}\n\nThey auto-expire after 7 days and the skip is fed back to the engine as a missed opportunity. Approve or skip them from your daily digest or the dashboard My Day tab.`
  } };
}).filter(Boolean);
